// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
interface IAgentIdRegistry {
    function handleOf(address wallet) external view returns (string memory);
}
contract AgenticalGlyphs is ERC721, ERC2981 {
    using Strings for uint256;
    uint256 public constant MAX_SUPPLY = 3500;
    uint256 public constant FREE_SUPPLY_CAP = 500;
    uint256 public constant CREATOR_RESERVE = 5;
    uint256 public constant MAX_PAID_PER_WALLET = 5;
    IAgentIdRegistry public constant REGISTRY = IAgentIdRegistry(0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F);
    address payable public immutable PAYOUT_ADDRESS;
    uint256 public immutable PRICE;
    uint256 public totalMinted;
    uint16[5] public tierRemaining;
    mapping(uint256 => uint256) public tokenSeeds;
    mapping(address => bool) public walletFreeMinted;
    mapping(bytes32 => bool) public agentIdFreeMinted;
    mapping(address => uint256) public walletPaidMints;
    mapping(bytes32 => uint256) public agentIdPaidMints;
    event Minted(
        address indexed to,
        uint256 indexed tokenId,
        uint8 tier,
        string agentId
    );
    constructor(address payable payTo, uint256 mintPrice) ERC721("Agentical Glyphs", "GLYPH") {
        require(payTo != address(0), "Invalid payout address");
        PAYOUT_ADDRESS = payTo;
        PRICE = mintPrice;
        _setDefaultRoyalty(payTo, 200);
        tierRemaining[0] = 1000;
        tierRemaining[1] = 1000;
        tierRemaining[2] = 500;
        tierRemaining[3] = 500;
        tierRemaining[4] = 500;
        for (uint256 i = 1; i <= CREATOR_RESERVE; i++) {
            _executeMint(payTo, "CREATOR_RESERVE");
        }
    }
    modifier onlyEOA() {
        require(msg.sender == tx.origin, "EOA only");
        _;
    }
    function mintFree(uint256 answer) external onlyEOA {
        require(totalMinted < FREE_SUPPLY_CAP, "Free phase ended");
        string memory handle = _validateAgentAndChallenge(msg.sender, answer);
        bytes32 handleHash = keccak256(bytes(handle));
        require(!walletFreeMinted[msg.sender], "Wallet already used free mint");
        require(!agentIdFreeMinted[handleHash], "Agent ID already used free mint");
        walletFreeMinted[msg.sender] = true;
        agentIdFreeMinted[handleHash] = true;
        _executeMint(msg.sender, handle);
    }
    function mintPaid(uint256 qty, uint256 answer) external payable onlyEOA {
        require(qty > 0, "Qty must be > 0");
        require(totalMinted >= FREE_SUPPLY_CAP, "Paid phase not started yet");
        require(totalMinted + qty <= MAX_SUPPLY, "Exceeds max supply");
        require(msg.value == PRICE * qty, "Incorrect BNB amount");
        string memory handle = _validateAgentAndChallenge(msg.sender, answer);
        bytes32 handleHash = keccak256(bytes(handle));
        require(walletPaidMints[msg.sender] + qty <= MAX_PAID_PER_WALLET, "Exceeds wallet paid limit");
        require(agentIdPaidMints[handleHash] + qty <= MAX_PAID_PER_WALLET, "Exceeds Agent ID paid limit");
        walletPaidMints[msg.sender] += qty;
        agentIdPaidMints[handleHash] += qty;
        for (uint256 i = 0; i < qty; i++) {
            _executeMint(msg.sender, handle);
        }
        (bool success, ) = PAYOUT_ADDRESS.call{value: msg.value}("");
        require(success, "BNB transfer failed");
    }
    function mint(uint256 qty, uint256 answer) external payable onlyEOA {
        require(qty > 0, "Qty must be > 0");
        require(totalMinted + qty <= MAX_SUPPLY, "Exceeds max supply");
        string memory handle = _validateAgentAndChallenge(msg.sender, answer);
        bytes32 handleHash = keccak256(bytes(handle));
        if (totalMinted < FREE_SUPPLY_CAP) {
            require(qty == 1, "Free mint is 1 per tx");
            require(msg.value == 0, "Free mint requires 0 BNB");
            require(!walletFreeMinted[msg.sender], "Wallet already used free mint");
            require(!agentIdFreeMinted[handleHash], "Agent ID already used free mint");
            walletFreeMinted[msg.sender] = true;
            agentIdFreeMinted[handleHash] = true;
            _executeMint(msg.sender, handle);
        } else {
            require(msg.value == PRICE * qty, "Incorrect BNB amount");
            require(walletPaidMints[msg.sender] + qty <= MAX_PAID_PER_WALLET, "Exceeds wallet paid limit");
            require(agentIdPaidMints[handleHash] + qty <= MAX_PAID_PER_WALLET, "Exceeds Agent ID paid limit");
            walletPaidMints[msg.sender] += qty;
            agentIdPaidMints[handleHash] += qty;
            for (uint256 i = 0; i < qty; i++) {
                _executeMint(msg.sender, handle);
            }
            (bool success, ) = PAYOUT_ADDRESS.call{value: msg.value}("");
            require(success, "BNB transfer failed");
        }
    }
    function _validateAgentAndChallenge(address wallet, uint256 answer) internal view returns (string memory) {
        string memory handle = agentIdOf(wallet);
        require(bytes(handle).length > 0, "Agent ID required");
        uint256 expected = _expectedAnswer(wallet);
        require(answer == expected, "Wrong answer");
        return handle;
    }
    function _expectedAnswer(address wallet) internal view returns (uint256) {
        (uint256 a, uint256 b) = _getChallengeFactors(wallet);
        string memory handle = agentIdOf(wallet);
        return (a * b) + bytes(handle).length;
    }
    function _getChallengeFactors(address wallet) internal pure returns (uint256 a, uint256 b) {
        bytes32 hash = keccak256(abi.encodePacked("Agentical Glyphs", wallet));
        a = 10 + (uint256(uint16(bytes2(hash))) % 90);
        b = 10 + (uint256(uint16(bytes2(hash << 16))) % 90);
    }
    function _executeMint(address to, string memory handle) internal {
        uint256 tokenId = totalMinted + 1;
        totalMinted = tokenId;
        uint8 tier = _drawTier(tokenId);
        uint256 rawSeed = uint256(
            keccak256(
                abi.encodePacked(
                    block.prevrandao,
                    blockhash(block.number - 1),
                    to,
                    tokenId,
                    tier
                )
            )
        );
        uint256 packedSeed = (rawSeed & ~uint256(0xFF)) | uint256(tier);
        tokenSeeds[tokenId] = packedSeed;
        _safeMint(to, tokenId);
        emit Minted(to, tokenId, tier, handle);
    }
    function _drawTier(uint256 tokenId) internal returns (uint8) {
        uint256 remainingTotal = MAX_SUPPLY - (tokenId - 1);
        require(remainingTotal > 0, "No tiers remaining");
        uint256 randIndex = uint256(
            keccak256(
                abi.encodePacked(
                    block.prevrandao,
                    blockhash(block.number - 1),
                    msg.sender,
                    tokenId
                )
            )
        ) % remainingTotal;
        uint256 accumulated = 0;
        for (uint8 t = 0; t < 5; t++) {
            accumulated += tierRemaining[t];
            if (randIndex < accumulated && tierRemaining[t] > 0) {
                tierRemaining[t]--;
                return t;
            }
        }
        for (uint8 t = 0; t < 5; t++) {
            if (tierRemaining[t] > 0) {
                tierRemaining[t]--;
                return t;
            }
        }
        revert("Tier pool exhausted");
    }
    function agentIdOf(address wallet) public view returns (string memory) {
        try REGISTRY.handleOf(wallet) returns (string memory handle) {
            return handle;
        } catch {
            return "";
        }
    }
    function challengeOf(address wallet) external pure returns (string memory question, uint256 a, uint256 b) {
        (a, b) = _getChallengeFactors(wallet);
        question = string(
            abi.encodePacked(
                "What is ",
                a.toString(),
                " x ",
                b.toString(),
                " plus the number of characters in your Agent ID (without .ai)?"
            )
        );
    }
    function isFreePhase() external view returns (bool) {
        return totalMinted < FREE_SUPPLY_CAP;
    }
    function freeLeft() external view returns (uint256) {
        if (totalMinted >= FREE_SUPPLY_CAP) return 0;
        return FREE_SUPPLY_CAP - totalMinted;
    }
    function tierLeft() external view returns (uint16 common, uint16 uncommon, uint16 rare, uint16 epic, uint16 legendary) {
        return (tierRemaining[0], tierRemaining[1], tierRemaining[2], tierRemaining[3], tierRemaining[4]);
    }
    function hasUsedFree(address wallet) external view returns (bool) {
        if (walletFreeMinted[wallet]) return true;
        string memory handle = agentIdOf(wallet);
        if (bytes(handle).length > 0) {
            return agentIdFreeMinted[keccak256(bytes(handle))];
        }
        return false;
    }
    function quote(address wallet, uint256 qty) external view returns (uint256 totalCost, uint256 allowedQty) {
        string memory handle = agentIdOf(wallet);
        bytes32 handleHash = bytes(handle).length > 0 ? keccak256(bytes(handle)) : bytes32(0);
        if (totalMinted < FREE_SUPPLY_CAP) {
            bool used = walletFreeMinted[wallet] || (handleHash != bytes32(0) && agentIdFreeMinted[handleHash]);
            if (used) {
                return (0, 0);
            } else {
                return (0, 1);
            }
        } else {
            uint256 walletUsed = walletPaidMints[wallet];
            uint256 agentUsed = handleHash != bytes32(0) ? agentIdPaidMints[handleHash] : 0;
            uint256 maxUsed = walletUsed > agentUsed ? walletUsed : agentUsed;
            if (maxUsed >= MAX_PAID_PER_WALLET) {
                return (0, 0);
            }
            uint256 remaining = MAX_PAID_PER_WALLET - maxUsed;
            uint256 supplyRemaining = MAX_SUPPLY - totalMinted;
            if (remaining > supplyRemaining) {
                remaining = supplyRemaining;
            }
            uint256 effectiveQty = qty > remaining ? remaining : qty;
            return (effectiveQty * PRICE, remaining);
        }
    }
    function tokensOfOwner(address wallet) external view returns (uint256[] memory) {
        uint256 count = balanceOf(wallet);
        uint256[] memory tokens = new uint256[](count);
        uint256 index = 0;
        for (uint256 i = 1; i <= totalMinted && index < count; i++) {
            if (_ownerOf(i) == wallet) {
                tokens[index] = i;
                index++;
            }
        }
        return tokens;
    }
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        uint256 seed = tokenSeeds[tokenId];
        uint8 tier = uint8(seed & 0xFF);
        string memory tierName = _getTierName(tier);
        string memory glyphShape = _getGlyphShape(seed);
        string memory mainColor = _getTierColor(tier);
        string memory glowColor = _getTierGlow(tier);
        string memory svg = _generateSVG(seed, tier, mainColor, glowColor);
        string memory svgBase64 = Base64.encode(bytes(svg));
        string memory json = Base64.encode(
            bytes(
                string(
                    abi.encodePacked(
                        '{"name":"Agentical Glyph #',
                        tokenId.toString(),
                        '","description":"Autonomous glowing generative glyph on BNB Chain. Fully on-chain SVG verified for AI agents.","image":"data:image/svg+xml;base64,',
                        svgBase64,
                        '","attributes":[{"trait_type":"Tier","value":"',
                        tierName,
                        '"},{"trait_type":"Glyph","value":"',
                        glyphShape,
                        '"},{"trait_type":"Color","value":"',
                        mainColor,
                        '"},{"trait_type":"Background","value":"Obsidian Vault"},{"trait_type":"Seed","value":"',
                        seed.toString(),
                        '"}]}'
                    )
                )
            )
        );
        return string(abi.encodePacked("data:application/json;base64,", json));
    }
    function contractURI() external view returns (string memory) {
        string memory logoSvg = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 500 500' width='500' height='500'><rect width='500' height='500' fill='#05070e'/><circle cx='250' cy='250' r='180' stroke='#F0B90B' stroke-width='6' fill='none'/><polygon points='250,110 370,320 130,320' stroke='#F0B90B' stroke-width='8' fill='none'/><circle cx='250' cy='250' r='60' stroke='#00F0FF' stroke-width='4' fill='none'/></svg>";
        string memory logoBase64 = Base64.encode(bytes(logoSvg));
        string memory json = Base64.encode(
            bytes(
                string(
                    abi.encodePacked(
                        '{"name":"Agentical Glyphs","description":"Autonomous on-chain visual identity artifacts on BNB Chain for .ai Agent IDs.","image":"data:image/svg+xml;base64,',
                        logoBase64,
                        '","external_link":"https://agentical-glyphs.pages.dev","seller_fee_basis_points":200,"fee_recipient":"',
                        Strings.toHexString(uint160(address(PAYOUT_ADDRESS)), 20),
                        '"}'
                    )
                )
            )
        );
        return string(abi.encodePacked("data:application/json;base64,", json));
    }
    function _generateSVG(
        uint256 seed,
        uint8 tier,
        string memory color,
        string memory glow
    ) internal pure returns (string memory) {
        uint256 shapeIdx = (seed >> 8) % 12;
        uint256 rot = (seed >> 16) % 360;
        uint256 markType = (seed >> 20) % 4;
        uint256 strokeWidth = 3 + ((seed >> 24) % 3);
        string memory primaryShape = _getShapeMarkup(shapeIdx, color, glow, strokeWidth);
        string memory innerMarks = _getInnerMarksMarkup(markType, color, glow);
        string memory aura = tier >= 3
            ? string(
                abi.encodePacked(
                    "<circle cx='250' cy='250' r='215' stroke='",
                    glow,
                    "' stroke-width='1.5' stroke-dasharray='4,8' fill='none'/>"
                )
            )
            : "";
        return string(
            abi.encodePacked(
                "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 500 500' width='100%' height='100%'>",
                "<defs>",
                "<radialGradient id='bg' cx='50%' cy='50%' r='65%'><stop offset='0%' stop-color='#0f1424'/><stop offset='100%' stop-color='#04060a'/></radialGradient>",
                "<filter id='glow' x='-30%' y='-30%' width='160%' height='160%'><feGaussianBlur stdDeviation='9' result='blur'/><feMerge><feMergeNode in='blur'/><feMergeNode in='SourceGraphic'/></feMerge></filter>",
                "</defs>",
                "<rect width='500' height='500' fill='url(#bg)'/>",
                "<g filter='url(#glow)' transform='rotate(",
                rot.toString(),
                " 250 250)'>",
                primaryShape,
                innerMarks,
                aura,
                "</g>",
                "<circle cx='250' cy='250' r='10' fill='",
                color,
                "'/>",
                "</svg>"
            )
        );
    }
    function _getShapeMarkup(
        uint256 shapeIdx,
        string memory color,
        string memory glow,
        uint256 sw
    ) internal pure returns (string memory) {
        string memory swStr = sw.toString();
        if (shapeIdx == 0) {
            return string(
                abi.encodePacked(
                    "<polygon points='250,70 390,150 390,350 250,430 110,350 110,150' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<polygon points='250,130 340,185 340,315 250,370 160,315 160,185' stroke='", glow, "' stroke-width='2' fill='none'/>"
                )
            );
        } else if (shapeIdx == 1) {
            return string(
                abi.encodePacked(
                    "<polygon points='250,80 390,380 110,380' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<polygon points='250,380 320,230 180,230' stroke='", glow, "' stroke-width='2' fill='none'/>"
                )
            );
        } else if (shapeIdx == 2) {
            return string(
                abi.encodePacked(
                    "<polygon points='250,70 377,123 430,250 377,377 250,430 123,377 70,250 123,123' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<rect x='140' y='140' width='220' height='220' stroke='", glow, "' stroke-width='2' transform='rotate(45 250 250)' fill='none'/>"
                )
            );
        } else if (shapeIdx == 3) {
            return string(
                abi.encodePacked(
                    "<circle cx='250' cy='250' r='160' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<ellipse cx='250' cy='250' rx='160' ry='70' stroke='", glow, "' stroke-width='2' fill='none'/>",
                    "<ellipse cx='250' cy='250' rx='160' ry='70' stroke='", glow, "' stroke-width='2' transform='rotate(60 250 250)' fill='none'/>",
                    "<ellipse cx='250' cy='250' rx='160' ry='70' stroke='", glow, "' stroke-width='2' transform='rotate(120 250 250)' fill='none'/>"
                )
            );
        } else if (shapeIdx == 4) {
            return string(
                abi.encodePacked(
                    "<rect x='110' y='110' width='280' height='280' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<rect x='170' y='170' width='160' height='160' stroke='", glow, "' stroke-width='2' fill='none'/>",
                    "<line x1='110' y1='110' x2='170' y2='170' stroke='", glow, "' stroke-width='1.5'/>",
                    "<line x1='390' y1='110' x2='330' y2='170' stroke='", glow, "' stroke-width='1.5'/>",
                    "<line x1='390' y1='390' x2='330' y2='330' stroke='", glow, "' stroke-width='1.5'/>",
                    "<line x1='110' y1='390' x2='170' y2='330' stroke='", glow, "' stroke-width='1.5'/>"
                )
            );
        } else if (shapeIdx == 5) {
            return string(
                abi.encodePacked(
                    "<circle cx='250' cy='250' r='120' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<polygon points='250,50 265,110 250,130 235,110' fill='", glow, "'/>",
                    "<polygon points='450,250 390,265 370,250 390,235' fill='", glow, "'/>",
                    "<polygon points='250,450 235,390 250,370 265,390' fill='", glow, "'/>",
                    "<polygon points='50,250 110,235 130,250 110,265' fill='", glow, "'/>"
                )
            );
        } else if (shapeIdx == 6) {
            return string(
                abi.encodePacked(
                    "<polygon points='250,70 405,340 95,340' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<polygon points='250,430 405,160 95,160' stroke='", glow, "' stroke-width='", swStr, "' fill='none'/>"
                )
            );
        } else if (shapeIdx == 7) {
            return string(
                abi.encodePacked(
                    "<circle cx='250' cy='250' r='175' stroke='", color, "' stroke-width='", swStr, "' stroke-dasharray='12,8' fill='none'/>",
                    "<circle cx='250' cy='250' r='115' stroke='", glow, "' stroke-width='2' fill='none'/>",
                    "<circle cx='250' cy='250' r='55' stroke='", color, "' stroke-width='2' stroke-dasharray='6,4' fill='none'/>"
                )
            );
              } else if (shapeIdx == 8) {
            return string(
                abi.encodePacked(
                    "<circle cx='250' cy='250' r='180' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<line x1='250' y1='70' x2='250' y2='100' stroke='", glow, "' stroke-width='4'/>",
                    "<line x1='430' y1='250' x2='400' y2='250' stroke='", glow, "' stroke-width='4'/>",
                    "<line x1='250' y1='430' x2='250' y2='400' stroke='", glow, "' stroke-width='4'/>",
                    "<line x1='70' y1='250' x2='100' y2='250' stroke='", glow, "' stroke-width='4'/>",
                    "<rect x='170' y='170' width='160' height='160' stroke='", glow, "' stroke-width='1.5' fill='none'/>"
                )
            );
        } else if (shapeIdx == 9) {
            return string(
                abi.encodePacked(
                    "<polygon points='250,60 410,250 250,440 90,250' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<circle cx='250' cy='250' r='100' stroke='", glow, "' stroke-width='2' fill='none'/>",
                    "<line x1='90' y1='250' x2='410' y2='250' stroke='", glow, "' stroke-width='1.5' stroke-dasharray='5,5'/>"
                )
            );
        } else if (shapeIdx == 10) {
            return string(
                abi.encodePacked(
                    "<rect x='120' y='120' width='260' height='260' rx='40' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<line x1='120' y1='120' x2='380' y2='380' stroke='", glow, "' stroke-width='2'/>",
                    "<line x1='380' y1='120' x2='120' y2='380' stroke='", glow, "' stroke-width='2'/>"
                )
