                abi.encodePacked(
                    "<path d='M250,70 L390,140 L390,280 Q250,440 250,440 Q110,280 110,140 Z' stroke='", color, "' stroke-width='", swStr, "' fill='none'/>",
                    "<circle cx='250' cy='230' r='60' stroke='", glow, "' stroke-width='2' fill='none'/>"
                )
            );
        }
    }
    function _getInnerMarksMarkup(
        uint256 markType,
        string memory color,
        string memory glow
    ) internal pure returns (string memory) {
        if (markType == 0) {
            return string(
                abi.encodePacked(
                    "<circle cx='250' cy='180' r='5' fill='", glow, "'/>",
                    "<circle cx='320' cy='250' r='5' fill='", glow, "'/>",
                    "<circle cx='250' cy='320' r='5' fill='", glow, "'/>",
                    "<circle cx='180' cy='250' r='5' fill='", glow, "'/>"
                )
            );
        } else if (markType == 1) {
            return string(
                abi.encodePacked(
                    "<line x1='210' y1='250' x2='290' y2='250' stroke='", color, "' stroke-width='2'/>",
                    "<line x1='250' y1='210' x2='250' y2='290' stroke='", color, "' stroke-width='2'/>"
                )
            );
        } else if (markType == 2) {
            return string(
                abi.encodePacked(
                    "<circle cx='250' cy='250' r='32' stroke='", glow, "' stroke-width='1.5' stroke-dasharray='4,4' fill='none'/>"
                )
            );
        } else {
            return string(
                abi.encodePacked(
                    "<polygon points='250,210 270,250 250,290 230,250' stroke='", glow, "' stroke-width='1.5' fill='none'/>"
                )
            );
        }
    }
    function _getGlyphShape(uint256 seed) internal pure returns (string memory) {
        uint256 geom = (seed >> 8) % 12;
        if (geom == 0) return "Hexagonal Matrix";
        if (geom == 1) return "Sacred Triforce";
        if (geom == 2) return "Celestial Octagram";
        if (geom == 3) return "Quantum Orbits";
        if (geom == 4) return "Hypercube Tesseract";
        if (geom == 5) return "Solar Flare";
        if (geom == 6) return "Merkaba Star";
        if (geom == 7) return "Singularity Core";
        if (geom == 8) return "Chrono Dial";
        if (geom == 9) return "Nexus Gateway";
        if (geom == 10) return "Vector Matrix";
        return "Aegis Seal";
    }
    function _getTierName(uint8 tier) internal pure returns (string memory) {
        if (tier == 4) return "Legendary";
        if (tier == 3) return "Epic";
        if (tier == 2) return "Rare";
        if (tier == 1) return "Uncommon";
        return "Common";
    }
    function _getTierColor(uint8 tier) internal pure returns (string memory) {
        if (tier == 4) return "#FFD700";
        if (tier == 3) return "#C084FC";
        if (tier == 2) return "#38BDF8";
        if (tier == 1) return "#34D399";
        return "#E2E8F0";
    }
    function _getTierGlow(uint8 tier) internal pure returns (string memory) {
        if (tier == 4) return "#F59E0B";
        if (tier == 3) return "#A855F7";
        if (tier == 2) return "#2563EB";
        if (tier == 1) return "#059669";
        return "#64748B";
    }
    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC2981) returns (bool) {
        return interfaceId == 0x2a55205a || super.supportsInterface(interfaceId);
    }
}
